const fs = require('fs');
const path = require('path');
const dir = __dirname;

const S = `*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}body{font-family:'Segoe UI',Tahoma,Geneva,Verdana,sans-serif;background:#1a1a2e;color:#e0e0e0;min-height:100vh;padding:2rem 1rem}.container{max-width:800px;margin:0 auto}h1{text-align:center;margin-bottom:.5rem;font-size:1.8rem;color:#fff}.subtitle{text-align:center;color:#8892b0;margin-bottom:2rem;font-size:1rem}.progress-bar-container{background:#0d1117;border-radius:10px;height:14px;margin-bottom:2rem;overflow:hidden}.progress-bar{background:linear-gradient(90deg,#0d6efd,#4dabf7);height:100%;width:0%;border-radius:10px;transition:width .4s ease}.progress-text{text-align:center;color:#8892b0;margin-bottom:1rem;font-size:.9rem}.card{background:#16213e;border-radius:12px;padding:2rem;margin-bottom:1.5rem;box-shadow:0 4px 20px rgba(0,0,0,.3)}.question-label{font-size:.85rem;color:#4dabf7;text-transform:uppercase;letter-spacing:1px;margin-bottom:.5rem}.question-text{font-size:1.15rem;margin-bottom:1.2rem;line-height:1.5;color:#fff}pre{background:#0d1117;border:1px solid #30363d;border-radius:8px;padding:1rem;margin-bottom:1.2rem;overflow-x:auto;font-size:.95rem}code{font-family:'Consolas','Fira Code','Courier New',monospace;color:#c9d1d9}.options{list-style:none}.options li{margin-bottom:.5rem}.options label{display:flex;align-items:center;gap:.75rem;padding:.8rem 1rem;background:#0d1117;border:2px solid #30363d;border-radius:8px;cursor:pointer;transition:border-color .2s,background .2s;font-size:1rem}.options label:hover{border-color:#4dabf7;background:#1c2a4a}.options input[type=radio]{accent-color:#0d6efd;width:18px;height:18px;flex-shrink:0}.btn{display:inline-block;padding:.7rem 2rem;border:none;border-radius:8px;font-size:1rem;font-weight:600;cursor:pointer;transition:background .2s,transform .1s}.btn-primary{background:#0d6efd;color:#fff}.btn-primary:hover{background:#3b82f6}.btn-primary:disabled{background:#374151;cursor:not-allowed}.btn-restart{background:#238636;color:#fff;margin-top:1rem;padding:.7rem 2rem;border:none;border-radius:8px;font-size:1rem;font-weight:600;cursor:pointer}.btn-restart:hover{background:#2ea043}.feedback{margin-top:1rem;padding:1rem 1.2rem;border-radius:8px;font-size:.95rem;line-height:1.5;display:none}.feedback.correct{background:#0f5132;border:1px solid #198754;color:#d1fae5;display:block}.feedback.wrong{background:#842029;border:1px solid #dc3545;color:#fdd;display:block}.score-card{text-align:center;padding:3rem 2rem}.score-card .score{font-size:3rem;font-weight:700;color:#4dabf7;margin-bottom:.5rem}.score-card .score-label{font-size:1.2rem;color:#8892b0;margin-bottom:1.5rem}.hidden{display:none}`;

const JS = 'let currentQuestion=0,score=0,answered=false;function renderQuestion(){const q=questions[currentQuestion],total=questions.length;document.getElementById("progressBar").style.width=((currentQuestion/total)*100)+"%";document.getElementById("progressText").textContent=`Question ${currentQuestion+1} / ${total}`;let html=`<div class="card"><p class="question-label">${q.label}</p><p class="question-text">${q.text}</p>`;if(q.code)html+=`<pre><code>${q.code}</code></pre>`;html+=`<ul class="options">`;q.options.forEach((opt,i)=>{html+=`<li><label><input type="radio" name="q" value="${i}"> ${opt}</label></li>`;});html+=`</ul><button class="btn btn-primary" id="validateBtn" onclick="validate()" disabled>Valider</button><div class="feedback" id="feedback"></div></div>`;document.getElementById("quizContainer").innerHTML=html;document.querySelectorAll(\'input[name="q"]\').forEach(r=>{r.addEventListener("change",()=>{document.getElementById("validateBtn").disabled=false;});});answered=false;}function validate(){if(answered){currentQuestion++;if(currentQuestion<questions.length)renderQuestion();else showScore();return;}answered=true;const selected=document.querySelector(\'input[name="q"]:checked\');if(!selected)return;const val=parseInt(selected.value),q=questions[currentQuestion];const fb=document.getElementById("feedback"),btn=document.getElementById("validateBtn");document.querySelectorAll(\'input[name="q"]\').forEach(r=>r.disabled=true);if(val===q.answer){score++;fb.className="feedback correct";fb.innerHTML=`<strong>Correct !</strong> ${q.explanation}`;}else{fb.className="feedback wrong";fb.innerHTML=`<strong>Incorrect.</strong> ${q.explanation}`;}btn.textContent=currentQuestion<questions.length-1?"Suivant":"Voir le score";}function showScore(){document.getElementById("quizContainer").classList.add("hidden");document.getElementById("progressBar").style.width="100%";document.getElementById("progressText").textContent="Termine !";const sc=document.getElementById("scoreContainer");sc.classList.remove("hidden");const pct=Math.round((score/questions.length)*100);let msg=pct===100?"Parfait !":pct>=60?"Bien joue !":"Continuez a reviser !";sc.innerHTML=`<div class="score">${score} / ${questions.length}</div><div class="score-label">${msg} (${pct}%)</div><button class="btn-restart" onclick="restart()">Recommencer</button>`;}function restart(){currentQuestion=0;score=0;answered=false;document.getElementById("scoreContainer").classList.add("hidden");document.getElementById("quizContainer").classList.remove("hidden");renderQuestion();}renderQuestion();';

function make(file, title, subtitle, questions) {
  const html = `<!DOCTYPE html>
<html lang="fr">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${title}</title>
  <style>${S}</style>
</head>
<body>
  <div class="container">
    <h1>${title}</h1>
    <p class="subtitle">${subtitle}</p>
    <div class="progress-bar-container"><div class="progress-bar" id="progressBar"></div></div>
    <p class="progress-text" id="progressText">Question 1 / 5</p>
    <div id="quizContainer"></div>
    <div id="scoreContainer" class="card score-card hidden"></div>
  </div>
  <script>
    const questions = ${JSON.stringify(questions)};
    ${JS}
  </script>
</body>
</html>`;
  fs.writeFileSync(path.join(dir, file), html, 'utf-8');
  console.log('OK', file);
}

// --- Section 03: Avance ---
make('quiz-03-01-vue-router.html','Quiz — Vue Router','Navigation SPA, routes dynamiques et guards',[
  {label:"Q1 — SPA",text:"Que signifie SPA et quel est son avantage principal ?",options:["Server Page Application — les pages sont generees cote serveur","Single Page Application — la page ne se recharge jamais, seul le contenu change","Simple Page Architecture — une seule page sans JavaScript","Secure Page Access — acces securise aux pages"],answer:1,explanation:"SPA = Single Page Application. Un seul fichier HTML est charge, et le routeur change dynamiquement le composant affiche sans recharger la page."},
  {label:"Q2 — Route dynamique",text:"Comment definit-on un parametre dynamique dans une route ?",code:"{ path: '/users/???', component: UserView }",options:["{ path: '/users/$id' }","{ path: '/users/:id' }","{ path: '/users/{id}' }","{ path: '/users/[id]' }"],answer:1,explanation:"En Vue Router, les parametres dynamiques sont prefixes par deux-points : /users/:id. La valeur est accessible via route.params.id."},
  {label:"Q3 — RouterView",text:"A quoi sert le composant &lt;RouterView /&gt; ?",options:["Il affiche la liste des routes disponibles","Il cree un lien de navigation","Il affiche le composant correspondant a la route actuelle","Il redirige vers la page d'accueil"],answer:2,explanation:"&lt;RouterView&gt; est le 'trou' dans le layout ou Vue Router insere le composant qui correspond a l'URL actuelle."},
  {label:"Q4 — Navigation guard",text:"A quoi sert un guard beforeEach ?",options:["A precharger les donnees de la page","A executer du code avant chaque navigation (ex: verifier l'authentification)","A animer la transition entre les pages","A mettre en cache les routes visitees"],answer:1,explanation:"beforeEach s'execute avant chaque changement de route. On l'utilise pour verifier l'authentification et rediriger vers /login si necessaire."},
  {label:"Q5 — RouterLink",text:"Pourquoi utiliser &lt;RouterLink&gt; au lieu de &lt;a href&gt; ?",options:["RouterLink est plus joli visuellement","RouterLink navigue sans recharger la page (navigation SPA), &lt;a href&gt; recharge entierement","RouterLink est obligatoire en Vue 3","&lt;a href&gt; ne fonctionne pas dans Vue"],answer:1,explanation:"&lt;RouterLink&gt; utilise le routeur pour changer de vue sans recharger la page. Un &lt;a href&gt; classique declencherait un rechargement complet."}
]);

make('quiz-03-02-pinia.html','Quiz — Pinia','State management avec le store officiel de Vue 3',[
  {label:"Q1 — Prop drilling",text:"Quel probleme Pinia resout-il principalement ?",options:["Les performances de rendu","Le prop drilling : passer des donnees a travers de nombreux niveaux de composants","La validation de formulaires","Le routage entre pages"],answer:1,explanation:"Sans store, pour partager des donnees entre composants non parent/enfant, il faut les passer a travers chaque niveau (prop drilling). Pinia centralise les donnees dans un store accessible partout."},
  {label:"Q2 — defineStore",text:"Comment cree-t-on un store Pinia ?",options:["new PiniaStore({ state: {} })","defineStore('id', { state, getters, actions })","createStore({ name: 'myStore' })","Vue.store('myStore', {})"],answer:1,explanation:"defineStore prend un identifiant unique et un objet contenant state (les donnees), getters (les computed) et actions (les fonctions)."},
  {label:"Q3 — Getters",text:"A quoi correspondent les getters dans un store Pinia ?",options:["A des evenements emis par le store","A des computed properties calculees a partir du state","A des middlewares de validation","A des watchers automatiques"],answer:1,explanation:"Les getters sont l'equivalent des computed dans un composant. Ils derivent des valeurs du state et sont mis en cache."},
  {label:"Q4 — Quand utiliser un store",text:"Quand faut-il utiliser un store Pinia plutot que des refs locales ?",options:["Toujours, pour toutes les donnees","Quand 2+ composants non parent/enfant ont besoin de la meme donnee","Uniquement pour les formulaires","Seulement en mode production"],answer:1,explanation:"Regle simple : si des composants freres ou eloignes partagent la meme donnee, utilisez un store. Les donnees locales a un seul composant restent dans des refs."},
  {label:"Q5 — Reactivite Pinia",text:"Le state d'un store Pinia est-il reactif ?",options:["Non, il faut appeler refresh() manuellement","Oui, le state est automatiquement reactif — les composants se mettent a jour quand il change","Seulement si on utilise reactive() dans le store","Seulement avec la syntaxe Options API"],answer:1,explanation:"Pinia rend automatiquement le state reactif. Tout composant qui utilise le store se met a jour quand le state change, sans action supplementaire."}
]);

make('quiz-03-03-tests-unitaires.html','Quiz — Tests unitaires Vue','Vitest, tester des composables et fonctions utilitaires',[
  {label:"Q1 — Vitest",text:"Quel est le role de Vitest dans un projet Vue ?",options:["Compiler le TypeScript","Executer les tests automatises rapidement, avec une API compatible Jest","Deployer l'application","Generer la documentation"],answer:1,explanation:"Vitest est un framework de test ultra-rapide base sur Vite. Il execute les tests unitaires et supporte TypeScript nativement."},
  {label:"Q2 — describe/it",text:"A quoi servent describe et it dans un test ?",options:["describe definit le composant, it definit les props","describe regroupe des tests lies, it definit un cas de test individuel","describe lance le serveur, it lance le navigateur","Les deux sont interchangeables"],answer:1,explanation:"describe() cree un groupe de tests lies (ex: 'useCounter'). it() (ou test()) definit un cas de test individuel avec une assertion."},
  {label:"Q3 — vi.fn()",text:"A quoi sert vi.fn() dans Vitest ?",options:["A creer un fichier de test","A creer une fonction mock (simulee) dont on peut verifier les appels","A generer des donnees aleatoires","A mesurer les performances"],answer:1,explanation:"vi.fn() cree un mock — une fausse fonction qu'on peut inspecter : combien de fois elle a ete appelee, avec quels arguments, etc."},
  {label:"Q4 — Tester un composable",text:"Comment teste-t-on un composable qui utilise ref et computed ?",options:["On le teste uniquement dans un navigateur","On l'appelle directement dans un test et on verifie les valeurs des refs retournees","On doit monter un composant complet pour chaque test","On ne peut pas tester les composables"],answer:1,explanation:"Les composables sont des fonctions. On les appelle dans un test, puis on verifie les .value des refs et computed retournees avec expect()."},
  {label:"Q5 — expect/toBe",text:"Que verifie expect(count.value).toBe(1) ?",options:["Que count est une ref","Que count.value est strictement egal a 1","Que count sera egal a 1 dans le futur","Que le composant affiche 1"],answer:1,explanation:"expect().toBe() est une assertion qui verifie l'egalite stricte (===). Si count.value n'est pas 1, le test echoue."}
]);

make('quiz-03-04-tests-composants.html','Quiz — Tests de composants','Vue Test Utils, mount, interactions et assertions',[
  {label:"Q1 — Vue Test Utils",text:"Quel est le role de Vue Test Utils ?",options:["Compiler les composants Vue","Monter des composants en memoire et les tester sans navigateur reel","Deployer les composants en production","Generer des composants automatiquement"],answer:1,explanation:"Vue Test Utils permet de creer (monter) des composants Vue en memoire, d'interagir avec eux et de verifier leur rendu, sans ouvrir un navigateur."},
  {label:"Q2 — mount vs shallowMount",text:"Quelle est la difference entre mount et shallowMount ?",options:["mount est plus rapide que shallowMount","mount rend les composants enfants, shallowMount les remplace par des stubs","shallowMount ne supporte pas TypeScript","Il n'y a aucune difference"],answer:1,explanation:"mount effectue un rendu complet (avec les enfants). shallowMount remplace les composants enfants par des stubs pour isoler le composant teste."},
  {label:"Q3 — wrapper.emitted()",text:"Comment verifie-t-on qu'un composant a emis un evenement ?",options:["wrapper.events('eventName')","wrapper.emitted('eventName')","wrapper.on('eventName')","wrapper.listen('eventName')"],answer:1,explanation:"wrapper.emitted('eventName') retourne un tableau des emissions. S'il est defini et non vide, l'evenement a ete emis."},
  {label:"Q4 — Simuler un clic",text:"Comment simule-t-on un clic dans un test de composant ?",options:["wrapper.click()","wrapper.find('button').trigger('click')","document.click()","wrapper.emit('click')"],answer:1,explanation:"On utilise wrapper.find() pour trouver l'element, puis .trigger('click') pour simuler l'evenement. Il faut souvent await car les mises a jour sont asynchrones."},
  {label:"Q5 — Props dans les tests",text:"Comment passe-t-on des props lors du montage d'un composant de test ?",code:"mount(MyComponent, { ??? })",options:["mount(MyComponent, { data: { title: 'Test' } })","mount(MyComponent, { props: { title: 'Test' } })","mount(MyComponent, 'Test')","mount(MyComponent).setProps({ title: 'Test' })"],answer:1,explanation:"On passe les props dans l'objet d'options de mount : mount(Component, { props: { title: 'Test' } })."}
]);

make('quiz-03-05-tests-integration.html','Quiz — Tests d\'integration','Tester plusieurs parties ensemble : composants, stores, API',[
  {label:"Q1 — Definition",text:"Qu'est-ce qu'un test d'integration ?",options:["Un test qui verifie le CSS d'un composant","Un test qui verifie que plusieurs parties fonctionnent bien ensemble","Un test qui mesure les performances","Un test qui verifie la syntaxe du code"],answer:1,explanation:"Un test d'integration verifie la collaboration entre plusieurs unites : un composant avec un store, un formulaire avec un appel API, etc."},
  {label:"Q2 — Mocking API",text:"Pourquoi mock-t-on (simule-t-on) les appels API dans les tests ?",options:["Pour accelerer le deploiement","Pour ne pas dependre d'un vrai serveur (pannes, lenteur, donnees changeantes)","Pour tester le CSS","Les vrais appels API sont interdits en TypeScript"],answer:1,explanation:"Les mocks garantissent des tests fiables, rapides et reproductibles. Un vrai serveur pourrait etre lent, en panne ou retourner des donnees differentes."},
  {label:"Q3 — Pinia dans les tests",text:"Comment fournit-on un store Pinia dans un test de composant ?",options:["On l'importe globalement avec import","On utilise createTestingPinia() dans les options de mount","On n'a pas besoin de Pinia dans les tests","On mocke manuellement chaque getter"],answer:1,explanation:"createTestingPinia() cree une instance Pinia de test ou les actions sont mockees par defaut. On la passe dans le plugin de mount."},
  {label:"Q4 — Pyramide des tests",text:"Quel type de test devrait etre le plus nombreux selon la pyramide des tests ?",options:["Tests E2E (end-to-end)","Tests d'integration","Tests unitaires","Tests de performance"],answer:2,explanation:"La pyramide des tests preconise beaucoup de tests unitaires (rapides, nombreux), moins de tests d'integration, et encore moins de tests E2E (lents, couteux)."},
  {label:"Q5 — Flux complet",text:"Quel est un exemple typique de test d'integration Vue ?",options:["Verifier qu'une ref contient la bonne valeur","L'utilisateur remplit un formulaire, clique sur soumettre, le store est mis a jour et l'API est appelee","Verifier que le CSS s'applique correctement","Mesurer le temps de chargement d'une page"],answer:1,explanation:"Un test d'integration typique simule un parcours utilisateur complet impliquant plusieurs couches : composant + store + API mockee."}
]);

make('quiz-03-06-tests-e2e-playwright.html','Quiz — Tests E2E Playwright','Tests end-to-end avec Playwright pour Vue/Nuxt',[
  {label:"Q1 — E2E",text:"Qu'est-ce qu'un test end-to-end (E2E) ?",options:["Un test qui verifie chaque ligne de code","Un test qui simule le parcours reel d'un utilisateur dans un vrai navigateur","Un test qui verifie les types TypeScript","Un test de performance du serveur"],answer:1,explanation:"Un test E2E ouvre un vrai navigateur, navigue sur le site, clique, remplit des formulaires et verifie le resultat — exactement comme un utilisateur reel."},
  {label:"Q2 — Playwright",text:"Quel avantage offre Playwright par rapport a Cypress ?",options:["Il est ecrit en Python","Il supporte Chrome, Firefox et Safari nativement avec une seule API","Il ne necessite pas Node.js","Il est plus ancien et mieux documente"],answer:1,explanation:"Playwright supporte les 3 moteurs de navigateur (Chromium, Firefox, WebKit/Safari) avec une API unifiee, la aussi contrairement a Cypress qui ne supporte que Chromium nativement."},
  {label:"Q3 — page.goto",text:"Que fait page.goto('/products') dans un test Playwright ?",options:["Il cree une nouvelle page","Il navigue vers l'URL /products dans le navigateur de test","Il telecharge le code source de la page","Il genere un screenshot"],answer:1,explanation:"page.goto() fait naviguer le navigateur vers l'URL specifiee, exactement comme si un utilisateur tapait l'adresse dans la barre de navigation."},
  {label:"Q4 — SSR et E2E",text:"Comment verifie-t-on que le SSR fonctionne dans un test E2E ?",options:["En verifiant que JavaScript est desactive","En inspectant le HTML initial de la reponse pour verifier que le contenu est present avant l'hydration","En mesurant la taille du bundle","En comptant le nombre de requetes reseau"],answer:1,explanation:"On intercepte la reponse HTML initiale et on verifie que le contenu est deja present dans le HTML brut (avant que JavaScript ne s'execute)."},
  {label:"Q5 — Selecteurs",text:"Quelle approche de selection d'elements est recommandee dans Playwright ?",options:["Selecteurs CSS complexes comme div > span.class:nth-child(2)","Selecteurs bases sur les roles accessibles : getByRole, getByText, getByLabel","Selecteurs par id genere automatiquement","Selecteurs XPath"],answer:1,explanation:"Les selecteurs bases sur les roles (getByRole('button', { name: 'Filtrer' })) sont plus resilients aux changements de structure HTML et testent aussi l'accessibilite."}
]);

make('quiz-03-07-msw-et-mocking-api.html','Quiz — MSW et mocking API','Mock Service Worker pour simuler les API dans les tests Vue',[
  {label:"Q1 — MSW",text:"Qu'est-ce que MSW (Mock Service Worker) ?",options:["Un framework de test complet","Un outil qui intercepte les requetes reseau au niveau du navigateur/Node pour les simuler","Un gestionnaire de state","Un bundler de code"],answer:1,explanation:"MSW intercepte les appels fetch/XHR et retourne des reponses simulees. Les composants ne savent pas qu'ils parlent a un mock — le code reste identique."},
  {label:"Q2 — Handlers",text:"A quoi servent les handlers dans MSW ?",options:["A gerer les erreurs JavaScript","A definir les reponses simulees pour chaque endpoint API","A gerer les evenements DOM","A configurer le bundler"],answer:1,explanation:"Les handlers definissent les routes mockees : http.get('/api/users', () => HttpResponse.json([...])) repond a chaque appel GET /api/users."},
  {label:"Q3 — Lifecycle",text:"Quel est le lifecycle typique de MSW dans les tests ?",options:["install → run → destroy","server.listen() → server.resetHandlers() → server.close()","start → mock → stop","init → fetch → cleanup"],answer:1,explanation:"beforeAll: server.listen() demarre l'interception. afterEach: server.resetHandlers() reinitialise. afterAll: server.close() arrete le serveur."},
  {label:"Q4 — Avantage sur vi.fn",text:"Quel avantage MSW a-t-il sur le mocking classique avec vi.fn() ?",options:["MSW est plus rapide","MSW intercepte au niveau reseau — le code applicatif n'est pas modifie, les tests sont plus realistes","MSW est obligatoire avec Vue","vi.fn() ne fonctionne pas avec fetch"],answer:1,explanation:"Avec MSW, le code applicatif fait de vrais appels fetch qui sont interceptes. On ne modifie pas les imports ni les modules, rendant les tests plus proches de la realite."},
  {label:"Q5 — Erreurs",text:"Comment simule-t-on une erreur serveur 500 avec MSW ?",options:["En debranchant Internet","En retournant new HttpResponse(null, { status: 500 }) dans le handler","En lancant une exception dans le composant","En modifiant le fichier .env"],answer:1,explanation:"On override le handler par defaut : server.use(http.get('/api/users', () => new HttpResponse(null, { status: 500 }))) pour simuler une panne serveur."}
]);

// --- Section 04: Expert ---
make('quiz-04-01-performance.html','Quiz — Performance Vue 3','Diagnostiquer et optimiser les performances front-end',[
  {label:"Q1 — Re-rendu",text:"Pourquoi les re-rendus inutiles sont-ils un probleme de performance ?",options:["Ils consomment de la bande passante","Ils forcent le navigateur a recalculer le layout et repeindre des pixels inutilement","Ils causent des erreurs TypeScript","Ils augmentent la taille du bundle"],answer:1,explanation:"Chaque re-rendu force le navigateur a recalculer la mise en page et a repeindre. Multiplier les re-rendus inutiles ralentit l'interface."},
  {label:"Q2 — shallowRef",text:"Quand utiliser shallowRef au lieu de ref ?",options:["Pour les valeurs primitives","Quand on a un objet volumineux dont on ne veut surveiller que la reference de premier niveau","Pour remplacer reactive","Pour les composants enfants"],answer:1,explanation:"shallowRef ne rend reactive que la reference de premier niveau. Utile pour les grosses listes ou objets dont on ne modifie pas les proprietes internes."},
  {label:"Q3 — Lazy loading",text:"A quoi sert le lazy loading de composants avec defineAsyncComponent ?",options:["A charger les composants plus tot","A ne charger le code d'un composant que quand il est necessaire, reduisant la taille du bundle initial","A rendre les composants plus rapides","A precharger tous les composants au demarrage"],answer:1,explanation:"Le lazy loading decoupe le bundle : le code d'un composant n'est telecharge que quand il est affiche pour la premiere fois, accelerant le chargement initial."},
  {label:"Q4 — v-once",text:"Que fait la directive v-once ?",options:["L'element n'est rendu qu'une seule fois et n'est jamais re-rendu, meme si les donnees changent","L'evenement ne se declenche qu'une fois","L'element est supprime apres le premier affichage","L'element est anime une seule fois"],answer:0,explanation:"v-once rend l'element une seule fois puis le considere comme du contenu statique. Utile pour du contenu qui ne changera jamais."},
  {label:"Q5 — Virtualisation",text:"Quelle technique utilise-t-on pour afficher de tres longues listes (10 000+ elements) ?",options:["Pagination cote serveur uniquement","La virtualisation : n'afficher que les elements visibles a l'ecran","Augmenter la RAM du navigateur","Utiliser v-show au lieu de v-if"],answer:1,explanation:"La virtualisation (vue-virtual-scroller) ne rend que les elements visibles dans la fenetre de defilement, meme si la liste contient des milliers d'elements."}
]);

make('quiz-04-02-ssr-et-hydration.html','Quiz — SSR et Hydration','Rendu serveur, CSR vs SSR, et hydration Vue/Nuxt',[
  {label:"Q1 — CSR vs SSR",text:"Quelle est la difference principale entre CSR et SSR ?",options:["CSR est plus securise que SSR","En CSR le navigateur construit la page, en SSR le serveur envoie le HTML deja construit","SSR ne supporte pas JavaScript","CSR necessite un serveur, SSR non"],answer:1,explanation:"CSR (Client-Side Rendering) : le navigateur recoit une page vide et la construit avec JavaScript. SSR (Server-Side Rendering) : le serveur genere le HTML complet."},
  {label:"Q2 — Hydration",text:"Qu'est-ce que l'hydration dans le contexte du SSR ?",options:["Le telechargement des images","Le processus qui attache les event listeners Vue au HTML statique envoye par le serveur","La mise en cache des pages","La compression du HTML"],answer:1,explanation:"L'hydration 'reactive' le HTML statique en y attachant la reactivite Vue et les event listeners, transformant une page statique en application interactive."},
  {label:"Q3 — SEO",text:"Pourquoi le SSR est-il meilleur pour le SEO que le CSR ?",options:["Le SSR est plus rapide","Les moteurs de recherche recoivent directement le HTML complet au lieu d'une page vide qui depend de JavaScript","Le SSR utilise des balises meta speciales","Le CSR bloque les robots Google"],answer:1,explanation:"Avec le CSR, Google recoit une page quasi vide et doit executer JavaScript pour voir le contenu. Avec le SSR, le contenu est dans le HTML initial, directement indexable."},
  {label:"Q4 — ISR",text:"Que signifie ISR (Incremental Static Regeneration) ?",options:["Un nouveau langage de programmation","La regeneration incrementale de pages statiques : les pages sont pre-generees puis mises a jour en arriere-plan","Un outil de debug Vue","Un pattern de test"],answer:1,explanation:"ISR combine les avantages du statique (rapide) et du dynamique (donnees fraiches). Les pages sont pre-generees puis regenerees en arriere-plan apres un delai configure."},
  {label:"Q5 — Erreur d'hydration",text:"Qu'est-ce qui cause une erreur d'hydration (hydration mismatch) ?",options:["Un CSS invalide","Le HTML genere cote serveur ne correspond pas a ce que Vue genere cote client","Un manque de memoire","Un probleme de reseau"],answer:1,explanation:"Si le HTML serveur differe de ce que Vue produirait cote client (ex: utiliser Date.now() ou Math.random()), Vue detecte un mismatch et affiche un warning."}
]);

make('quiz-04-03-architecture-front.html','Quiz — Architecture front-end','Organisation du code, structure par feature, barrel exports',[
  {label:"Q1 — Feature-based",text:"Qu'est-ce qu'une structure 'feature-based' ?",options:["Organiser les fichiers par type technique (components/, stores/, services/)","Organiser les fichiers par fonctionnalite metier (users/, products/, cart/)","Mettre tous les fichiers dans un seul dossier","Organiser par ordre alphabetique"],answer:1,explanation:"La structure feature-based regroupe tout ce qui concerne une fonctionnalite au meme endroit : composants, store, types, services. C'est plus maintenable pour les gros projets."},
  {label:"Q2 — Barrel export",text:"A quoi sert un fichier index.ts (barrel export) dans un dossier ?",options:["A configurer TypeScript","A centraliser et re-exporter les elements du dossier pour simplifier les imports","A definir le point d'entree de l'application","A configurer les tests"],answer:1,explanation:"Un barrel export re-exporte tout depuis un seul fichier : import { UserCard, UserForm } from './features/users' au lieu d'importer chaque fichier separement."},
  {label:"Q3 — Couche service",text:"Quel est le role de la couche service dans l'architecture ?",options:["Gerer le CSS global","Centraliser les appels API pour separer la logique reseau des composants","Gerer les animations","Definir les routes"],answer:1,explanation:"La couche service (ex: userService.ts) encapsule les appels API. Les composants n'appellent jamais fetch directement — ils passent par le service."},
  {label:"Q4 — Separation des responsabilites",text:"Pourquoi un composant ne devrait-il pas appeler fetch directement ?",options:["fetch ne fonctionne pas dans les composants Vue","Pour separer les responsabilites : le composant gere l'affichage, le service gere le reseau","Pour des raisons de securite","fetch est obsolete"],answer:1,explanation:"La separation des responsabilites rend le code testable, maintenable et reutilisable. Changer l'URL de l'API ne modifie que le service, pas 20 composants."},
  {label:"Q5 — Types partages",text:"Ou place-t-on les interfaces TypeScript partagees entre plusieurs features ?",options:["Dans chaque composant qui les utilise","Dans un dossier types/ ou shared/ accessible a toutes les features","Dans le fichier main.ts","Dans le package.json"],answer:1,explanation:"Les types partages vont dans un dossier dedie (types/ ou shared/types/). Les types specifiques a une feature restent dans le dossier de cette feature."}
]);

make('quiz-04-04-patterns-entreprise.html','Quiz — Patterns d\'entreprise','Service layer, repository pattern, error boundaries',[
  {label:"Q1 — Service layer",text:"Quel est le role du pattern Service Layer ?",options:["Gerer les styles CSS","Encapsuler la logique metier et les appels API dans des classes/fonctions dediees, separees des composants","Gerer le routage","Creer des composants generiques"],answer:1,explanation:"Le Service Layer isole la logique metier. Les composants appellent userService.getAll() sans savoir si les donnees viennent d'une API REST, GraphQL ou du cache."},
  {label:"Q2 — Error boundary",text:"A quoi sert un Error Boundary en Vue ?",options:["A valider les formulaires","A capturer les erreurs de ses composants enfants sans planter toute l'application","A gerer les erreurs 404","A debugger le CSS"],answer:1,explanation:"Un Error Boundary (via onErrorCaptured) attrape les erreurs des composants enfants et affiche un fallback au lieu de laisser l'application entiere planter."},
  {label:"Q3 — Composant generique",text:"Qu'est-ce qu'un composant generique (ex: DataTable&lt;T&gt;) ?",options:["Un composant sans props","Un composant parametre par un type TypeScript, reutilisable avec differents types de donnees","Un composant qui n'a pas de style","Un composant invisible"],answer:1,explanation:"Un composant generique accepte un parametre de type : DataTable&lt;User&gt; et DataTable&lt;Product&gt; partagent le meme code mais manipulent des types differents."},
  {label:"Q4 — Quand appliquer",text:"Quand les patterns d'entreprise sont-ils necessaires ?",options:["Toujours, des le premier composant","Pour les gros projets en equipe, pas pour les petits projets","Uniquement pour les applications mobiles","Seulement si on utilise Nuxt"],answer:1,explanation:"Appliquer ces patterns sur un petit projet est de la sur-ingenierie. Ils prennent tout leur sens dans les projets en equipe avec beaucoup de fonctionnalites."},
  {label:"Q5 — DRY",text:"Que signifie le principe DRY ?",options:["Delete, Refactor, Yield","Don't Repeat Yourself — ne pas dupliquer la logique, la centraliser","Dynamic Runtime Yield","Debug, Review, Yell"],answer:1,explanation:"DRY (Don't Repeat Yourself) incite a factoriser la logique dupliquee dans des fonctions, composables ou services reutilisables."}
]);

// --- Section 05: Nuxt 3 ---
make('quiz-05-01-introduction-nuxt.html','Quiz — Nuxt 3 Introduction','Framework Vue full-stack, auto-import, SSR integre',[
  {label:"Q1 — Nuxt vs Vue",text:"Quel est le rapport entre Nuxt 3 et Vue 3 ?",options:["Ce sont deux frameworks concurrents","Nuxt 3 est un framework construit par-dessus Vue 3, ajoutant le routeur auto, le SSR et le backend integre","Nuxt remplace Vue","Vue est une extension de Nuxt"],answer:1,explanation:"Nuxt 3 est un meta-framework base sur Vue 3. Il ajoute le file-based routing, le SSR, les auto-imports et les server routes."},
  {label:"Q2 — Auto-import",text:"Que signifie 'auto-import' dans Nuxt 3 ?",options:["Les packages npm s'installent automatiquement","Les composables Vue (ref, computed) et les composants sont importes automatiquement sans ecrire import","Les images sont optimisees automatiquement","Les tests s'executent automatiquement"],answer:1,explanation:"Nuxt auto-importe ref, computed, useRoute, etc. On peut les utiliser directement sans ecrire import { ref } from 'vue'."},
  {label:"Q3 — File-based routing",text:"Comment fonctionnent les routes dans Nuxt 3 ?",options:["On configure manuellement chaque route dans un fichier router.ts","Chaque fichier .vue dans pages/ cree automatiquement une route correspondante","On utilise des decorateurs sur les composants","On ecrit les routes dans nuxt.config.ts"],answer:1,explanation:"pages/index.vue → route /. pages/about.vue → route /about. pages/users/[id].vue → route /users/:id. C'est le file-based routing."},
  {label:"Q4 — SSR",text:"Le SSR est-il actif par defaut dans Nuxt 3 ?",options:["Non, il faut l'activer manuellement","Oui, Nuxt 3 active le SSR par defaut","Seulement en mode production","Seulement avec une configuration specifique"],answer:1,explanation:"Nuxt 3 active le SSR par defaut. On peut le desactiver avec ssr: false dans nuxt.config.ts pour un mode SPA classique."},
  {label:"Q5 — Server routes",text:"Ou cree-t-on les routes API backend dans Nuxt 3 ?",options:["Dans le dossier pages/","Dans le dossier components/","Dans le dossier server/api/","Dans le fichier nuxt.config.ts"],answer:2,explanation:"Les fichiers dans server/api/ deviennent des endpoints API. Par exemple, server/api/users.ts cree l'endpoint GET /api/users."}
]);

make('quiz-05-02-pages-et-layouts.html','Quiz — Pages et Layouts Nuxt','File-based routing, layouts et NuxtPage',[
  {label:"Q1 — Layout",text:"Quelle est la difference entre un layout et une page dans Nuxt ?",options:["Un layout est une page speciale","Le layout est la structure fixe (menu, footer), la page est le contenu qui change selon l'URL","Les layouts n'existent pas dans Nuxt 3","Un layout est un composant sans style"],answer:1,explanation:"Le layout est le cadre (navigation, pied de page). La page est le contenu qui change. Le layout utilise &lt;slot /&gt; pour indiquer ou la page s'insere."},
  {label:"Q2 — Route dynamique Nuxt",text:"Comment cree-t-on une route dynamique /users/:id dans Nuxt 3 ?",options:["pages/users/$id.vue","pages/users/[id].vue","pages/users/:id.vue","pages/users/{id}.vue"],answer:1,explanation:"Dans Nuxt 3, les crochets [] definissent un parametre dynamique. pages/users/[id].vue cree la route /users/:id."},
  {label:"Q3 — NuxtPage",text:"A quoi sert &lt;NuxtPage /&gt; dans un layout ?",options:["A creer une nouvelle page","A afficher le contenu de la page correspondant a la route actuelle","A naviguer vers une autre page","A precharger les pages"],answer:1,explanation:"&lt;NuxtPage /&gt; est le remplacant de &lt;RouterView /&gt; dans Nuxt. Il affiche le composant page qui correspond a l'URL actuelle."},
  {label:"Q4 — NuxtLink",text:"Pourquoi utiliser &lt;NuxtLink&gt; au lieu de &lt;a href&gt; dans Nuxt ?",options:["NuxtLink est plus joli","NuxtLink effectue une navigation SPA sans rechargement et prefetch les pages liees","NuxtLink est obligatoire","&lt;a href&gt; ne fonctionne pas dans Nuxt"],answer:1,explanation:"&lt;NuxtLink&gt; navigue sans recharger la page (navigation cote client) et peut prefetcher les pages liees quand le lien est visible, pour une navigation instantanee."},
  {label:"Q5 — Middleware",text:"A quoi servent les middleware de page dans Nuxt ?",options:["A gerer le CSS","A executer du code avant d'afficher une page (ex: verifier l'authentification)","A compresser les images","A generer le sitemap"],answer:1,explanation:"Les middleware s'executent avant le rendu d'une page. On les utilise pour la verification d'authentification, la redirection, ou le chargement de donnees prealables."}
]);

make('quiz-05-03-data-fetching.html','Quiz — Data Fetching Nuxt','useFetch, useAsyncData et gestion des donnees',[
  {label:"Q1 — useFetch",text:"Que retourne useFetch('/api/users') dans Nuxt ?",options:["Uniquement les donnees","Un objet { data, pending, error, refresh }","Une promesse simple","Un tableau d'utilisateurs"],answer:1,explanation:"useFetch retourne un objet reactif avec data (les donnees), pending (chargement en cours), error (eventuelle erreur) et refresh (fonction pour recharger)."},
  {label:"Q2 — SSR et fetch",text:"Quand useFetch est-il execute dans un contexte SSR ?",options:["Uniquement dans le navigateur","D'abord sur le serveur, puis les donnees sont transmises au client sans re-fetch","Uniquement pendant le build","A chaque clic de l'utilisateur"],answer:1,explanation:"En SSR, useFetch s'execute sur le serveur. Les donnees sont serialisees dans le HTML et transmises au client pour eviter un double appel."},
  {label:"Q3 — useFetch vs useAsyncData",text:"Quelle est la difference entre useFetch et useAsyncData ?",options:["Aucune difference","useFetch est un wrapper simplifie autour de useAsyncData + $fetch","useAsyncData est obsolete","useFetch ne supporte que GET"],answer:1,explanation:"useFetch combine useAsyncData et $fetch en une seule fonction. useAsyncData est plus flexible car on peut utiliser n'importe quelle source de donnees."},
  {label:"Q4 — refresh()",text:"A quoi sert la fonction refresh() retournee par useFetch ?",options:["A rafraichir le CSS","A relancer la requete API pour obtenir des donnees fraiches","A recharger la page entiere","A vider le cache du navigateur"],answer:1,explanation:"refresh() relance l'appel API et met a jour les donnees reactives. Utile apres une modification (ajout, suppression) pour afficher les donnees a jour."},
  {label:"Q5 — $fetch",text:"Quelle est la difference entre $fetch et fetch natif dans Nuxt ?",options:["Il n'y a aucune difference","$fetch est un wrapper Nuxt qui fonctionne cote serveur et client, avec deserialization JSON automatique","$fetch est plus lent","$fetch ne supporte pas les headers"],answer:1,explanation:"$fetch (de la librairie ofetch) fonctionne universellement (serveur + client), parse automatiquement le JSON et gere mieux les erreurs que fetch natif."}
]);

make('quiz-05-04-server-routes.html','Quiz — Server Routes Nuxt','Routes API backend integrees dans Nuxt 3',[
  {label:"Q1 — Server route",text:"Qu'est-ce qu'une server route dans Nuxt 3 ?",options:["Une route qui redirige vers un autre site","Du code qui s'execute sur le serveur et repond aux requetes API","Une route visible uniquement sur mobile","Un middleware de routage"],answer:1,explanation:"Les server routes sont des endpoints API qui s'executent cote serveur. Elles ont acces aux bases de donnees, secrets et operations impossibles cote client."},
  {label:"Q2 — defineEventHandler",text:"Quelle fonction utilise-t-on pour creer un handler de server route ?",options:["createHandler()","defineEventHandler()","serverRoute()","apiHandler()"],answer:1,explanation:"defineEventHandler((event) => { ... }) est la fonction Nitro/Nuxt pour definir un handler qui recoit l'evenement HTTP et retourne une reponse."},
  {label:"Q3 — Methodes HTTP",text:"Comment distingue-t-on un GET d'un POST dans les server routes Nuxt ?",options:["Avec un if dans le handler","En nommant le fichier : users.get.ts pour GET, users.post.ts pour POST","Avec un parametre de query","On ne peut pas distinguer"],answer:1,explanation:"Nuxt utilise la convention de nommage : fichier.get.ts, fichier.post.ts, fichier.delete.ts pour router vers le bon handler selon la methode HTTP."},
  {label:"Q4 — readBody",text:"Comment lit-on le body d'une requete POST dans une server route ?",options:["event.body","await readBody(event)","request.json()","getBody(event)"],answer:1,explanation:"readBody(event) est la fonction Nitro pour lire et parser le corps de la requete. Elle est asynchrone car elle doit lire le stream."},
  {label:"Q5 — Securite",text:"Pourquoi les cles API doivent-elles etre dans les server routes et pas dans le code client ?",options:["Les server routes sont plus rapides","Le code client est visible dans le navigateur — les cles seraient exposees. Le code serveur reste prive","Les cles ne fonctionnent pas cote client","C'est une convention sans raison technique"],answer:1,explanation:"Le code JavaScript client est telecharge et visible par tous. Les cles API dans le code client seraient accessibles a n'importe qui. Le code serveur n'est jamais envoye au navigateur."}
]);

make('quiz-05-05-seo-et-meta.html','Quiz — SEO et Meta Nuxt','Optimisation moteurs de recherche, useHead, meta tags',[
  {label:"Q1 — SEO",text:"Que signifie SEO ?",options:["Server Engine Optimization","Search Engine Optimization — optimiser son site pour etre trouve sur Google","Secure Encrypted Output","Single Entry Operation"],answer:1,explanation:"SEO = Search Engine Optimization. C'est l'ensemble des techniques pour ameliorer le classement d'un site dans les resultats de recherche Google."},
  {label:"Q2 — useHead",text:"A quoi sert le composable useHead() dans Nuxt ?",options:["A charger des polices de caracteres","A definir dynamiquement le title, les meta description et les balises Open Graph de la page","A gerer le header HTTP","A creer un composant header"],answer:1,explanation:"useHead() permet de modifier les balises &lt;head&gt; (title, meta, link, script) dynamiquement pour chaque page, essentiel pour le SEO."},
  {label:"Q3 — Meta description",text:"Pourquoi la meta description est-elle importante pour le SEO ?",options:["Elle change la couleur du site sur Google","Elle apparait comme resume sous le titre dans les resultats de recherche Google","Elle est obligatoire pour que le site fonctionne","Elle accelere le chargement"],answer:1,explanation:"La meta description apparait comme texte descriptif dans les resultats Google. Une bonne description encourage les utilisateurs a cliquer."},
  {label:"Q4 — Open Graph",text:"A quoi servent les balises Open Graph (og:title, og:image) ?",options:["A optimiser les performances","A controler l'apercu affiche quand on partage le lien sur les reseaux sociaux","A securiser le site","A definir les couleurs du theme"],answer:1,explanation:"Les balises OG controlent le titre, la description et l'image affichees quand quelqu'un partage votre lien sur Facebook, Twitter, LinkedIn, etc."},
  {label:"Q5 — SSR et SEO",text:"Pourquoi le SSR de Nuxt est-il benefique pour le SEO ?",options:["Le SSR rend le site plus joli","Les moteurs de recherche recoivent le HTML complet des la premiere requete, sans devoir executer JavaScript","Le SSR bloque les robots malveillants","Le SSR compresse automatiquement les images"],answer:1,explanation:"Avec le SSR, le contenu est dans le HTML initial. Google n'a pas besoin d'executer JavaScript pour voir le contenu, ce qui ameliore l'indexation."}
]);

// --- Section 06: Storybook ---
make('quiz-06-01-storybook-setup.html','Quiz — Storybook Setup','Installation et configuration de Storybook pour Vue 3',[
  {label:"Q1 — Storybook",text:"A quoi sert Storybook ?",options:["A gerer les routes de l'application","A developper et visualiser chaque composant isolement, en dehors de l'application","A deployer l'application","A ecrire des tests E2E"],answer:1,explanation:"Storybook est un outil qui permet de voir chaque composant individuellement avec differentes variantes (props, etats), sans lancer toute l'application."},
  {label:"Q2 — Installation",text:"Quelle commande initialise Storybook dans un projet Vue ?",options:["pnpm add storybook","npx storybook@latest init","vue add storybook","npm create storybook"],answer:1,explanation:"npx storybook@latest init detecte automatiquement le framework (Vue 3 + Vite) et installe tout ce qu'il faut."},
  {label:"Q3 — Configuration",text:"Ou se trouve la configuration principale de Storybook ?",options:["Dans nuxt.config.ts","Dans le dossier .storybook/ a la racine","Dans vite.config.ts","Dans package.json"],answer:1,explanation:"Le dossier .storybook/ contient main.ts (config du framework, addons) et preview.ts (decorateurs globaux, parametres)."},
  {label:"Q4 — preview.ts",text:"A quoi sert le fichier preview.ts de Storybook ?",options:["A previsualiser les images","A configurer les decorateurs globaux, parametres par defaut et themes pour toutes les stories","A generer les previews de PR","A tester les composants"],answer:1,explanation:"preview.ts configure ce qui s'applique a toutes les stories : styles globaux, decorateurs (ex: wrapper i18n/router), parametres par defaut."},
  {label:"Q5 — Avantage",text:"Quel est l'avantage principal de Storybook pour une equipe ?",options:["Il remplace les tests unitaires","Il sert de documentation vivante des composants et facilite la collaboration entre devs et designers","Il est obligatoire pour publier sur npm","Il genere le CSS automatiquement"],answer:1,explanation:"Storybook documente visuellement les composants avec leurs variantes. Les designers voient le resultat, les devs comprennent les props disponibles."}
]);

make('quiz-06-02-stories.html','Quiz — Ecrire des stories','Format CSF, args, decorateurs et variantes',[
  {label:"Q1 — Story",text:"Qu'est-ce qu'une story dans Storybook ?",options:["Un fichier de test","Un exemple concret d'un composant dans un etat particulier (variante de props)","Un composant Vue special","Un fichier de configuration"],answer:1,explanation:"Une story montre un composant dans un etat specifique : bouton primaire, bouton desactive, bouton en chargement. Chaque story = une variante."},
  {label:"Q2 — meta",text:"A quoi sert l'objet meta (export default) dans un fichier .stories.ts ?",options:["A exporter le composant","A definir les informations generales : quel composant, ses args par defaut, ses decorateurs","A configurer TypeScript","A definir les tests"],answer:1,explanation:"L'objet meta configure la story globalement : le composant associe, les args par defaut, les decorateurs, le titre dans la sidebar Storybook."},
  {label:"Q3 — args",text:"Que sont les 'args' dans une story Storybook ?",options:["Les arguments de ligne de commande","Les props passees au composant, modifiables interactivement dans le panneau Controls","Les parametres de configuration de Vite","Les variables d'environnement"],answer:1,explanation:"Les args definissent les props du composant. Storybook genere automatiquement un panneau Controls qui permet de les modifier en temps reel."},
  {label:"Q4 — Decorateurs",text:"A quoi servent les decorateurs dans une story ?",options:["A ajouter du CSS decoratif","A envelopper le composant dans un contexte (ex: fournir un router, un store, un theme)","A generer de la documentation","A animer les transitions"],answer:1,explanation:"Les decorateurs wrappent le composant dans un conteneur. Utile pour fournir un contexte (Pinia store, i18n, router) ou un layout (padding, fond)."},
  {label:"Q5 — Play function",text:"A quoi sert une play function dans une story ?",options:["A lancer une animation","A simuler des interactions utilisateur (clic, saisie) automatiquement dans la story","A jouer de la musique","A executer les tests unitaires"],answer:1,explanation:"Les play functions simulent des interactions dans la story. On peut cliquer sur des boutons, remplir des champs et verifier le resultat, comme un mini-test."}
]);

make('quiz-06-03-design-system.html','Quiz — Design System','Tokens, composants atomiques et charte graphique',[
  {label:"Q1 — Design system",text:"Qu'est-ce qu'un design system ?",options:["Un logiciel de design graphique","Un ensemble de regles, tokens et composants reutilisables qui garantissent la coherence visuelle","Un framework CSS comme Tailwind","Un outil de prototypage"],answer:1,explanation:"Un design system regroupe les tokens (couleurs, espacements), les composants (boutons, cartes) et les regles d'utilisation pour une interface coherente."},
  {label:"Q2 — Design tokens",text:"Qu'est-ce qu'un design token ?",options:["Un jeton d'authentification","Une valeur de design nommee et reutilisable (couleur, espacement, taille de police)","Un composant invisible","Un fichier de configuration"],answer:1,explanation:"Un token est une variable de design : --color-primary: #0d6efd, --spacing-md: 16px. Changer le token met a jour toute l'application."},
  {label:"Q3 — Atomic design",text:"Que sont les 'atomes' dans la methodologie Atomic Design ?",options:["Les plus petits composants indivisibles (bouton, input, label, icone)","Les pages completes de l'application","Les animations CSS","Les variables TypeScript"],answer:0,explanation:"Les atomes sont les briques elementaires : un bouton, un champ de texte, une icone. On les combine en molecules (champ + label), puis en organismes (formulaire complet)."},
  {label:"Q4 — Avantage",text:"Quel est l'avantage principal d'un design system pour une equipe ?",options:["Il remplace les developpeurs","Tout le monde utilise les memes composants et valeurs, garantissant la coherence et accelerant le developpement","Il est obligatoire pour le deploiement","Il genere le code automatiquement"],answer:1,explanation:"Un design system evite que chaque dev reinvente les boutons avec des styles differents. Changer la couleur principale = modifier une seule variable."},
  {label:"Q5 — Storybook et design system",text:"Quel role joue Storybook dans un design system ?",options:["Il remplace le design system","Il sert de catalogue interactif ou l'on peut voir et tester chaque composant du design system","Il genere les tokens automatiquement","Il est utilise uniquement pour les tests"],answer:1,explanation:"Storybook documente visuellement le design system : chaque composant avec ses variantes, ses props et ses exemples d'utilisation."}
]);

// --- Section 07: CI/CD ---
make('quiz-07-01-pipeline-ci.html','Quiz — Pipeline CI','Integration continue, GitHub Actions, lint, tests et build',[
  {label:"Q1 — CI",text:"Que fait la CI (Continuous Integration) ?",options:["Elle deploie l'application automatiquement","Elle verifie automatiquement le code a chaque push (lint, types, tests, build)","Elle genere la documentation","Elle cree les composants"],answer:1,explanation:"La CI execute automatiquement une serie de verifications a chaque push : linting, typecheck, tests, build. Si une etape echoue, on est prevenu immediatement."},
  {label:"Q2 — GitHub Actions",text:"Ou place-t-on les fichiers de configuration GitHub Actions ?",options:["Dans le dossier .github/workflows/","Dans le fichier package.json","Dans le dossier src/ci/","Dans le fichier vite.config.ts"],answer:0,explanation:"Les workflows GitHub Actions sont des fichiers YAML dans .github/workflows/ (ex: ci.yml). Ils definissent les etapes a executer."},
  {label:"Q3 — Pipeline",text:"Quel est l'ordre typique des etapes dans un pipeline CI Vue ?",options:["Deploy → Test → Build → Lint","Install → Lint → Typecheck → Test → Build","Test → Install → Deploy → Lint","Build → Deploy → Test → Install"],answer:1,explanation:"L'ordre logique est : installer les dependances, verifier le style (lint), verifier les types (typecheck), executer les tests, puis construire le bundle."},
  {label:"Q4 — Echec",text:"Que se passe-t-il si une etape du pipeline echoue ?",options:["Les etapes suivantes s'executent quand meme","Le pipeline s'arrete et le developpeur est notifie de l'erreur","Le code est deploye avec un avertissement","L'etape est ignoree automatiquement"],answer:1,explanation:"Si une etape echoue (ex: un test plante), le pipeline s'arrete. Le code n'est pas deploye et le developpeur recoit une notification."},
  {label:"Q5 — Cache",text:"Pourquoi met-on en cache le dossier node_modules dans le pipeline CI ?",options:["Pour economiser de l'espace disque","Pour eviter de retelecharger toutes les dependances a chaque execution, accelerant le pipeline","Pour securiser les dependances","Le cache est obligatoire"],answer:1,explanation:"Sans cache, pnpm install retelecharge tout a chaque push. Le cache des dependances reduit le temps du pipeline de plusieurs minutes."}
]);

make('quiz-07-02-deploiement.html','Quiz — Deploiement','Mettre en ligne avec Vercel, Netlify, variables d\'environnement',[
  {label:"Q1 — Deploiement",text:"Qu'est-ce que le deploiement d'une application ?",options:["Ecrire le code source","Mettre l'application sur un serveur accessible sur Internet","Installer les dependances","Executer les tests"],answer:1,explanation:"Deployer = rendre l'application accessible aux utilisateurs via une URL publique sur Internet, en la placant sur un serveur ou une plateforme cloud."},
  {label:"Q2 — Build",text:"Que fait la commande pnpm build ?",options:["Elle lance le serveur de developpement","Elle cree une version optimisee (minifiee, compressees) de l'application pour la production","Elle installe les dependances","Elle execute les tests"],answer:1,explanation:"pnpm build compile et optimise le code (minification, tree-shaking, compression) pour produire des fichiers statiques prets pour la production."},
  {label:"Q3 — Vercel/Netlify",text:"Quel avantage offrent Vercel et Netlify pour le deploiement ?",options:["Ils sont les seuls hebergeurs existants","Ils detectent le framework, buildent et deployent automatiquement a chaque push Git","Ils fournissent un editeur de code","Ils remplacent GitHub"],answer:1,explanation:"Vercel et Netlify connectent le repo Git, detectent Vue/Nuxt, executent le build et deployent automatiquement. Un push = un deploiement."},
  {label:"Q4 — Variables d'env",text:"Pourquoi ne doit-on pas committer les variables d'environnement (.env) dans Git ?",options:["Elles ralentissent Git","Elles contiennent souvent des secrets (cles API, mots de passe) qui seraient visibles publiquement","Elles ne sont pas compatibles avec GitHub","Git ne supporte pas les fichiers .env"],answer:1,explanation:"Les fichiers .env contiennent des secrets. S'ils sont commits dans un repo public, n'importe qui peut voir vos cles API et mots de passe."},
  {label:"Q5 — Preview deploy",text:"Qu'est-ce qu'un preview deployment ?",options:["Un deploiement en mode debug","Un deploiement temporaire cree automatiquement pour chaque pull request, permettant de tester avant merge","Un deploiement qui expire apres 24h","Un deploiement sans CSS"],answer:1,explanation:"Les preview deployments creent une URL temporaire pour chaque PR. L'equipe peut tester les changements avant de les fusionner dans la branche principale."}
]);

make('quiz-07-03-monitoring.html','Quiz — Monitoring','Suivi des erreurs, performance et analytics en production',[
  {label:"Q1 — Monitoring",text:"Pourquoi le monitoring est-il necessaire en production ?",options:["Pour respecter la loi","Parce qu'on ne peut pas voir les erreurs des utilisateurs depuis son ordinateur de developpement","Pour accelerer le site","Pour generer des rapports de vente"],answer:1,explanation:"En production, les erreurs surviennent sur les navigateurs des utilisateurs. Sans monitoring, on ne sait pas que l'app plante pour certains utilisateurs."},
  {label:"Q2 — Error tracking",text:"Quel outil est couramment utilise pour le suivi des erreurs front-end ?",options:["Google Analytics","Sentry — il capture automatiquement les erreurs JavaScript et les remonte avec leur stack trace","Lighthouse","ESLint"],answer:1,explanation:"Sentry intercepte les erreurs non gerees en production, enregistre le stack trace, le navigateur, l'URL et d'autres contextes pour faciliter le debug."},
  {label:"Q3 — 3 piliers",text:"Quels sont les 3 piliers du monitoring ?",options:["HTML, CSS, JavaScript","Error tracking (erreurs), performance (vitesse), analytics (usage)","Frontend, backend, database","Dev, staging, production"],answer:1,explanation:"Les 3 piliers sont : error tracking (detecter les bugs), performance monitoring (mesurer la vitesse), analytics (comprendre le comportement des utilisateurs)."},
  {label:"Q4 — Core Web Vitals",text:"Que mesurent les Core Web Vitals ?",options:["La taille du code source","Les metriques de performance utilisateur : LCP (chargement), FID (interactivite), CLS (stabilite visuelle)","Le nombre de visiteurs","La securite du site"],answer:1,explanation:"Les Core Web Vitals de Google mesurent l'experience utilisateur reelle : vitesse de chargement (LCP), reactivite (FID/INP), stabilite visuelle (CLS)."},
  {label:"Q5 — Source maps",text:"A quoi servent les source maps en production ?",options:["A afficher une carte geographique des utilisateurs","A traduire les erreurs du code minifie vers le code source original pour faciliter le debug","A generer le plan du site","A compresser les images"],answer:1,explanation:"En production le code est minifie. Les source maps permettent a Sentry de montrer l'erreur dans le code original lisible, pas dans le code minifie incomprehensible."}
]);

// --- Section 08: API typees ---
make('quiz-08-01-graphql-vue3.html','Quiz — GraphQL avec Vue 3','Queries, mutations et integration avec Vue',[
  {label:"Q1 — REST vs GraphQL",text:"Quelle est la difference principale entre REST et GraphQL ?",options:["REST est plus recent que GraphQL","REST retourne des donnees fixes par endpoint, GraphQL permet de choisir exactement les champs voulus","GraphQL ne supporte pas les mutations","REST est plus rapide"],answer:1,explanation:"Avec REST, GET /users retourne TOUS les champs. Avec GraphQL, on demande exactement les champs voulus : { user { name email } }."},
  {label:"Q2 — Over-fetching",text:"Qu'est-ce que le 'over-fetching' ?",options:["Faire trop de requetes","Recevoir plus de donnees que necessaire d'une API","Envoyer trop de donnees au serveur","Mettre trop de donnees en cache"],answer:1,explanation:"L'over-fetching survient quand l'API retourne des champs inutiles. Ex: on veut juste le nom, mais GET /user retourne aussi l'adresse, l'avatar, la date de creation..."},
  {label:"Q3 — Query vs Mutation",text:"Quelle est la difference entre une query et une mutation en GraphQL ?",options:["Les queries sont plus rapides","Les queries lisent des donnees (GET), les mutations les modifient (POST, PUT, DELETE)","Les mutations sont obsoletes","Il n'y a pas de difference"],answer:1,explanation:"query = lire des donnees (equivalent de GET). mutation = modifier des donnees (equivalent de POST/PUT/DELETE). C'est la separation lecture/ecriture."},
  {label:"Q4 — useQuery",text:"A quoi sert useQuery dans @vue/apollo-composable ?",options:["A creer des requetes SQL","A executer une query GraphQL et retourner les donnees reactives (result, loading, error)","A interroger le DOM","A creer un formulaire de recherche"],answer:1,explanation:"useQuery execute une query GraphQL et retourne des refs reactives : result (donnees), loading (en cours), error (erreur). Le composant se met a jour automatiquement."},
  {label:"Q5 — Schema",text:"Qu'est-ce que le schema dans GraphQL ?",options:["Le CSS du site","Le contrat qui definit les types de donnees, les queries et mutations disponibles sur l'API","La base de donnees","Le fichier de configuration"],answer:1,explanation:"Le schema GraphQL definit la structure des donnees (types), les queries disponibles (lecture) et les mutations (ecriture). C'est la documentation vivante de l'API."}
]);

make('quiz-08-02-trpc.html','Quiz — tRPC','TypeScript Remote Procedure Call, typage de bout en bout',[
  {label:"Q1 — tRPC",text:"Quel est le principe fondamental de tRPC ?",options:["Utiliser GraphQL avec TypeScript","Appeler les fonctions du serveur comme si elles etaient locales, avec un typage partage entre front et back","Remplacer REST par des WebSockets","Generer automatiquement les API"],answer:1,explanation:"tRPC partage les types TypeScript entre le frontend et le backend. Le frontend appelle les procedures serveur avec un typage complet, sans schema ni generation de code."},
  {label:"Q2 — Avantage",text:"Quel avantage tRPC a-t-il sur REST/GraphQL ?",options:["Il est plus rapide au runtime","Pas de schema a maintenir : les types TypeScript SONT le contrat entre front et back","Il supporte plus de langages","Il est plus simple a deployer"],answer:1,explanation:"Avec REST/GraphQL, on doit maintenir un schema/documentation separement. Avec tRPC, les types TypeScript servent directement de contrat — tout est synchronise automatiquement."},
  {label:"Q3 — Prerequis",text:"Quel est le prerequis pour utiliser tRPC ?",options:["Utiliser React","Le frontend ET le backend doivent etre en TypeScript (monorepo recommande)","Avoir une base de donnees PostgreSQL","Utiliser Docker"],answer:1,explanation:"tRPC fonctionne grace au partage de types TypeScript. Il faut donc que le front et le back soient tous les deux en TypeScript, idealement dans un monorepo."},
  {label:"Q4 — Procedures",text:"Quels sont les deux types principaux de procedures tRPC ?",options:["query et mutation — comme GraphQL","get et set","read et write","request et response"],answer:0,explanation:"tRPC utilise query (lecture de donnees) et mutation (modification de donnees), similaire a GraphQL mais sans le langage de requete."},
  {label:"Q5 — Zod et tRPC",text:"Quel role joue Zod dans tRPC ?",options:["Il remplace TypeScript","Il valide les inputs des procedures au runtime tout en inferant les types","Il gere l'authentification","Il genere la documentation"],answer:1,explanation:"Zod valide les donnees entrantes au runtime (securite) ET infere les types TypeScript automatiquement. C'est le bridge entre typage statique et validation dynamique."}
]);

// --- Section 09: Accessibilite (02 and 03 only) ---
make('quiz-09-02-aria-et-vue.html','Quiz — ARIA et Vue 3','Roles, proprietes et etats ARIA dans les composants Vue',[
  {label:"Q1 — Premiere regle ARIA",text:"Quelle est la premiere regle d'ARIA ?",options:["Toujours utiliser ARIA sur chaque element","Ne pas utiliser ARIA si le HTML natif suffit — un &lt;button&gt; est preferable a &lt;div role='button'&gt;","ARIA est obligatoire pour l'accessibilite","ARIA remplace le HTML semantique"],answer:1,explanation:"La premiere regle d'ARIA est de ne pas l'utiliser si le HTML natif suffit. Un &lt;button&gt; est nativement focusable et annonce correctement par les lecteurs d'ecran."},
  {label:"Q2 — aria-live",text:"A quoi sert aria-live='polite' ?",options:["A rendre le site plus rapide","A annoncer les changements de contenu dynamique aux lecteurs d'ecran quand l'utilisateur est inactif","A ajouter une animation","A charger du contenu en arriere-plan"],answer:1,explanation:"En SPA, le contenu change sans rechargement de page. aria-live='polite' previent les lecteurs d'ecran des changements pour que les utilisateurs non-voyants soient informes."},
  {label:"Q3 — Roles ARIA",text:"Que definit un role ARIA sur un element ?",options:["Sa couleur","Ce qu'EST l'element pour les technologies d'assistance (dialog, tab, alert, etc.)","Sa position sur la page","Sa taille"],answer:1,explanation:"Le role ARIA indique aux technologies d'assistance la nature de l'element : role='dialog' = une fenetre modale, role='tab' = un onglet, role='alert' = une alerte."},
  {label:"Q4 — Focus trap",text:"Qu'est-ce qu'un focus trap et quand l'utiliser ?",options:["Un piege pour les virus","Un mecanisme qui empeche le focus de sortir d'un conteneur — a utiliser quand une modale est ouverte","Un outil de debug","Un type de test automatise"],answer:1,explanation:"Quand une modale est ouverte, le focus clavier doit rester a l'interieur. Un focus trap empeche Tab de naviguer vers les elements caches derriere la modale."},
  {label:"Q5 — aria-label",text:"Quand utilise-t-on aria-label sur un bouton ?",options:["Toujours, sur chaque bouton","Quand le bouton n'a pas de texte visible (ex: bouton avec icone seule)","Pour remplacer le texte du bouton","Pour styler le bouton"],answer:1,explanation:"Si un bouton ne contient qu'une icone (pas de texte visible), aria-label fournit un texte descriptif aux lecteurs d'ecran : aria-label='Fermer'."}
]);

make('quiz-09-03-audit-a11y.html','Quiz — Audit d\'accessibilite','Outils automatises, tests manuels et lecteurs d\'ecran',[
  {label:"Q1 — Couverture auto",text:"Quel pourcentage de problemes d'accessibilite les outils automatises detectent-ils ?",options:["100 %","90 %","30 a 40 %","5 %"],answer:2,explanation:"Les outils automatises (Lighthouse, axe-core) ne detectent que 30-40 % des problemes. Le test manuel (clavier) et les lecteurs d'ecran sont indispensables."},
  {label:"Q2 — Lighthouse",text:"Comment accede-t-on a Lighthouse dans Chrome ?",options:["En installant une extension payante","En ouvrant DevTools (F12) → onglet Lighthouse → cocher Accessibility","En tapant lighthouse dans la barre d'adresse","En modifiant le fichier de configuration"],answer:1,explanation:"Lighthouse est integre a Chrome DevTools. Onglet Lighthouse, cocher Accessibility, puis Analyze page load pour obtenir un score et des recommandations."},
  {label:"Q3 — Test clavier",text:"Pourquoi le test au clavier est-il essentiel pour l'accessibilite ?",options:["C'est plus rapide que la souris","Les utilisateurs avec handicap moteur ou visuel naviguent au clavier — il faut verifier que tout est accessible sans souris","Le clavier est plus precis","Les tests automatises ne fonctionnent qu'au clavier"],answer:1,explanation:"Naviguer avec Tab, Entree et Echap verifie que tous les elements interactifs sont atteignables et utilisables sans souris."},
  {label:"Q4 — axe-core CI",text:"Comment integre-t-on les tests d'accessibilite dans la CI ?",options:["On teste manuellement avant chaque deploy","On utilise axe-core dans les tests automatises pour verifier l'accessibilite a chaque push","On envoie le site a un auditeur","On utilise uniquement Lighthouse"],answer:1,explanation:"axe-core peut etre integre dans les tests Vitest/Playwright pour verifier automatiquement l'accessibilite a chaque push, bloquant les regressions."},
  {label:"Q5 — Lecteur d'ecran",text:"Quel est le lecteur d'ecran gratuit le plus utilise sur Windows ?",options:["VoiceOver","JAWS","NVDA","Orca"],answer:2,explanation:"NVDA (NonVisual Desktop Access) est gratuit et open-source. VoiceOver est sur Mac, JAWS est payant, Orca est sur Linux."}
]);

// --- Section 10: i18n ---
make('quiz-10-01-vue-i18n.html','Quiz — vue-i18n','Internationalisation avec Vue 3, traductions et formatage',[
  {label:"Q1 — i18n",text:"Que signifie i18n ?",options:["Un protocole reseau","Internationalization (i + 18 lettres + n) — adapter un logiciel a differentes langues","Un framework CSS","Un outil de tests"],answer:1,explanation:"i18n est l'abreviation d'internationalization. C'est le processus de conception d'un logiciel pour qu'il puisse s'adapter a differentes langues et regions."},
  {label:"Q2 — $t()",text:"A quoi sert la fonction $t() (ou t() en Composition API) ?",options:["A tester le code","A traduire une cle en texte dans la langue active : t('nav.home') → 'Accueil' ou 'Home'","A transformer du texte en majuscules","A telecharger des traductions"],answer:1,explanation:"t('nav.home') cherche la traduction correspondante dans les messages de la locale active et retourne le texte traduit."},
  {label:"Q3 — Pluralisation",text:"Comment gere-t-on la pluralisation dans vue-i18n ?",options:["Avec des if/else dans le template","Avec le separateur | dans la chaine : 'aucun article | un article | {count} articles'","Avec une fonction custom","La pluralisation n'est pas supportee"],answer:1,explanation:"vue-i18n utilise le pipe | pour separer les formes : zero | singulier | pluriel. t('cart.items', 3) retourne '3 articles'."},
  {label:"Q4 — legacy: false",text:"Pourquoi faut-il mettre legacy: false dans la configuration de vue-i18n ?",options:["Pour desactiver les anciennes traductions","Pour activer le mode Composition API (useI18n) au lieu du mode Options API","Pour supporter les anciens navigateurs","Pour desactiver le cache"],answer:1,explanation:"legacy: false active le mode Composition API de vue-i18n, permettant d'utiliser useI18n() dans les composants avec &lt;script setup&gt;."},
  {label:"Q5 — Formatage dates",text:"Quelle fonction vue-i18n utilise-t-on pour formater les dates selon la locale ?",options:["formatDate()","d() — elle formate une date selon les regles de la locale active","new Date().toLocaleString()","t('date')"],answer:1,explanation:"d(new Date(), 'long') formate la date selon la locale : '17 mars 2026' en francais, 'March 17, 2026' en anglais."}
]);

make('quiz-10-02-strategies-avancees-i18n.html','Quiz — Strategies avancees i18n','SEO multilingue, lazy loading des traductions, RTL',[
  {label:"Q1 — lang attribute",text:"Pourquoi faut-il mettre a jour l'attribut lang de &lt;html&gt; quand la langue change ?",options:["Pour changer la police de caracteres","Pour que les moteurs de recherche et lecteurs d'ecran connaissent la langue du contenu","Pour activer le correcteur orthographique","C'est purement decoratif"],answer:1,explanation:"L'attribut lang sur &lt;html&gt; indique aux moteurs de recherche, lecteurs d'ecran et outils de traduction la langue du document."},
  {label:"Q2 — hreflang",text:"A quoi servent les balises hreflang pour le SEO ?",options:["A traduire automatiquement le contenu","A indiquer aux moteurs de recherche que la meme page existe dans d'autres langues","A charger les polices de caracteres","A compresser les traductions"],answer:1,explanation:"Les balises hreflang indiquent a Google que /fr/about et /en/about sont la meme page en differentes langues, evitant le contenu duplique."},
  {label:"Q3 — Lazy loading traductions",text:"Pourquoi charger les traductions de facon asynchrone (lazy loading) ?",options:["C'est obligatoire avec vue-i18n","Pour ne pas charger toutes les langues au demarrage, reduisant la taille du bundle initial","Pour traduire plus rapidement","Pour supporter plus de langues"],answer:1,explanation:"Si l'app supporte 10 langues, charger toutes les traductions au demarrage alourdit le bundle. Le lazy loading ne charge que la langue active."},
  {label:"Q4 — RTL",text:"Que signifie RTL et quelles langues sont concernees ?",options:["Real-Time Loading — toutes les langues","Right-To-Left — les langues comme l'arabe et l'hebreu qui s'ecrivent de droite a gauche","Return-To-Login — les langues avec authentification","Render-Time Limit — aucune langue"],answer:1,explanation:"RTL = Right-To-Left. L'arabe, l'hebreu et le persan s'ecrivent de droite a gauche. L'interface doit s'adapter (menus, alignements) en miroir."},
  {label:"Q5 — Extraction",text:"A quoi servent les outils d'extraction de chaines (ex: vue-i18n-extract) ?",options:["A compresser les traductions","A detecter automatiquement les cles de traduction utilisees dans le code et les cles manquantes","A generer des traductions automatiques","A valider la grammaire"],answer:1,explanation:"Les outils d'extraction scannent le code pour trouver tous les appels a t() et detecter les cles manquantes ou inutilisees dans les fichiers de traduction."}
]);

// --- Section 11: Auth et securite ---
make('quiz-11-01-authentification.html','Quiz — Authentification','JWT, sessions, OAuth2 et flux d\'authentification',[
  {label:"Q1 — Auth vs Authz",text:"Quelle est la difference entre authentification et autorisation ?",options:["Ce sont deux mots pour la meme chose","Authentification = prouver qui tu es. Autorisation = verifier ce que tu as le droit de faire","Authentification est cote client, autorisation cote serveur","L'autorisation remplace l'authentification"],answer:1,explanation:"L'authentification verifie l'identite (login). L'autorisation verifie les droits d'acces (peut-il acceder a la page admin ?). Ce sont deux etapes distinctes."},
  {label:"Q2 — JWT",text:"Qu'est-ce qu'un JWT (JSON Web Token) ?",options:["Un format de base de donnees","Un jeton signe contenant les informations utilisateur, utilise pour l'authentification sans session serveur","Un type de cookie","Un protocole de chiffrement"],answer:1,explanation:"Un JWT est un texte encode contenant le payload (id, role) et une signature. Le serveur peut verifier son authenticite sans consulter une base de donnees."},
  {label:"Q3 — Access vs Refresh token",text:"Pourquoi utilise-t-on deux tokens (access + refresh) ?",options:["Pour doubler la securite","L'access token est courte duree (minutes) pour limiter les risques, le refresh token permet d'en obtenir un nouveau sans se reconnecter","Le refresh token est plus rapide","C'est obligatoire avec JWT"],answer:1,explanation:"L'access token expire vite (15min) pour limiter les degats en cas de vol. Le refresh token (longue duree) permet silencieusement d'obtenir un nouvel access token."},
  {label:"Q4 — Stockage token",text:"Ou est-il recommande de stocker les tokens dans une app Vue/Nuxt SSR ?",options:["Dans localStorage uniquement","Dans un cookie httpOnly secure pour le refresh token, et en memoire pour l'access token","Dans le code source","Dans le URL"],answer:1,explanation:"Les cookies httpOnly ne sont pas accessibles par JavaScript (protection XSS). L'access token en memoire disparait a la fermeture de l'onglet, limitant les risques."},
  {label:"Q5 — Navigation guard auth",text:"Comment protege-t-on les routes necessitant une authentification ?",options:["En cachant les liens dans le menu","Avec un navigation guard (beforeEach) qui verifie le token et redirige vers /login si absent","En desactivant JavaScript","En mettant un mot de passe dans l'URL"],answer:1,explanation:"Un guard beforeEach verifie la presence d'un token valide avant chaque navigation. Si l'utilisateur n'est pas connecte, il est redirige vers la page de login."}
]);

make('quiz-11-02-securite-front.html','Quiz — Securite front-end','XSS, CSRF, CORS et bonnes pratiques',[
  {label:"Q1 — XSS",text:"Qu'est-ce qu'une attaque XSS (Cross-Site Scripting) ?",options:["Un virus dans le CSS","L'injection de code JavaScript malveillant dans une page web, qui s'execute dans le navigateur des visiteurs","Un type de firewall","Une attaque sur le serveur"],answer:1,explanation:"Le XSS permet a un attaquant d'injecter du JavaScript malveillant (ex: via un commentaire) qui s'execute dans le navigateur des autres visiteurs, volant cookies ou donnees."},
  {label:"Q2 — Vue et XSS",text:"Comment Vue protege-t-il par defaut contre le XSS ?",options:["Vue bloque toutes les requetes reseau","Vue echappe automatiquement le contenu dans les doubles accolades {{ }}, empechant l'interpretation du HTML","Vue utilise un firewall integre","Vue ne protege pas contre le XSS"],answer:1,explanation:"Les {{ }} echappent automatiquement le HTML : &lt;script&gt; est affiche comme texte, pas execute. Attention : v-html n'echappe PAS et peut donc etre dangereux."},
  {label:"Q3 — CSRF",text:"Qu'est-ce qu'une attaque CSRF ?",options:["Un probleme de CSS","Un site malveillant qui envoie des requetes au serveur en se faisant passer pour l'utilisateur connecte","Un type de compression","Une erreur TypeScript"],answer:1,explanation:"CSRF (Cross-Site Request Forgery) : un site malveillant profite du cookie de session de l'utilisateur pour envoyer des requetes non autorisees au serveur."},
  {label:"Q4 — CORS",text:"A quoi sert CORS ?",options:["A compresser les reponses","A controler quels domaines peuvent faire des requetes a votre API","A chiffrer les donnees","A mettre en cache les requetes"],answer:1,explanation:"CORS (Cross-Origin Resource Sharing) permet au serveur de specifier quels domaines sont autorises a faire des requetes. Sans CORS correct, le navigateur bloque les requetes cross-origin."},
  {label:"Q5 — v-html danger",text:"Pourquoi v-html est-il considere comme dangereux ?",options:["Il est plus lent que {{ }}","Il interprete le HTML brut sans echappement, permettant l'execution de scripts malveillants si le contenu vient d'un utilisateur","Il ne fonctionne pas en SSR","Il casse le CSS"],answer:1,explanation:"v-html insere du HTML brut dans le DOM. Si le contenu vient d'un utilisateur, il pourrait contenir &lt;script&gt; malveillant qui serait execute. N'utilisez v-html qu'avec du contenu de confiance."}
]);

make('quiz-11-03-rbac-et-permissions.html','Quiz — RBAC et permissions','Controle d\'acces base sur les roles dans Vue',[
  {label:"Q1 — RBAC",text:"Que signifie RBAC ?",options:["Remote Backend Access Control","Role-Based Access Control — controle d'acces base sur les roles","Real-time Browser Authentication","Reactive Binding And Components"],answer:1,explanation:"RBAC = Role-Based Access Control. Chaque utilisateur a un role (admin, editor, viewer) qui determine ses droits d'acces."},
  {label:"Q2 — Role vs Permission",text:"Quelle est la difference entre un role et une permission ?",options:["Ce sont des synonymes","Un role est une etiquette (admin), une permission est un droit precis (users:delete). Un role regroupe des permissions","Un role est cote serveur, une permission cote client","Une permission est plus importante qu'un role"],answer:1,explanation:"Le role (admin, editor) est une etiquette attribuee a l'utilisateur. Il regroupe des permissions specifiques (users:read, users:write, users:delete)."},
  {label:"Q3 — Directive v-permission",text:"Quel est l'interet d'une directive custom v-permission dans Vue ?",options:["Elle est plus rapide que v-if","Elle masque les elements de l'interface auxquels l'utilisateur n'a pas acces, de facon declarative","Elle remplace l'authentification","Elle securise les requetes API"],answer:1,explanation:"v-permission='users:delete' masque le bouton de suppression si l'utilisateur n'a pas cette permission. C'est declaratif et reutilisable."},
  {label:"Q4 — Front vs Back",text:"Pourquoi la verification des permissions cote front ne suffit-elle pas ?",options:["Le front est plus rapide","Le front peut etre contourne (DevTools, requetes directes). Le serveur DOIT aussi verifier les permissions","Le front n'a pas acces aux permissions","Les permissions n'existent pas cote front"],answer:1,explanation:"Masquer un bouton n'empeche pas un utilisateur technique d'envoyer la requete directement. Le serveur doit toujours re-verifier les permissions a chaque requete."},
  {label:"Q5 — Route guard RBAC",text:"Comment restreint-on l'acces a une page admin dans Vue Router ?",options:["En cachant le lien dans le menu","Avec un guard qui verifie le role/permissions de l'utilisateur et redirige si insuffisant","En mettant la page dans un dossier secret","En utilisant v-if sur le RouterView"],answer:1,explanation:"Un navigation guard verifie si l'utilisateur a le role requis (ex: admin) avant d'afficher la page. Si non, il est redirige vers une page 403 ou l'accueil."}
]);

