make('quiz-12-01-tanstack-query.html','Quiz — TanStack Query','useQuery, useMutation, cache et gestion des donnees serveur',[
  {label:"Q1 — TanStack Query",text:"Quel probleme TanStack Query resout-il ?",options:["Il remplace Vue Router","Il gere automatiquement le cache, le chargement, les erreurs et le rafraichissement des donnees serveur","Il compile le TypeScript","Il genere les composants"],answer:1,explanation:"TanStack Query automatise tout ce qu'on fait manuellement avec fetch : isLoading, error, cache, refetch, invalidation. Plus besoin de gerer ces etats a la main."},
  {label:"Q2 — queryKey",text:"A quoi sert la queryKey dans useQuery ?",options:["A nommer la variable qui contient les donnees","A identifier la requete de maniere unique pour le cache et l'invalidation","A definir la methode HTTP","A securiser la requete"],answer:1,explanation:"La queryKey identifie chaque requete dans le cache. ['users'] et ['users', 42] sont deux entrees de cache differentes. On invalide par cle pour rafraichir."},
  {label:"Q3 — useQuery vs useMutation",text:"Quelle est la difference entre useQuery et useMutation ?",options:["useQuery est plus rapide","useQuery lit des donnees (GET), useMutation les modifie (POST, PUT, DELETE)","useMutation remplace useQuery en Vue 3.4","Il n'y a pas de difference"],answer:1,explanation:"useQuery est pour les lectures (afficher une liste). useMutation est pour les ecritures (creer, modifier, supprimer). Apres une mutation, on invalide les queries concernees."},
  {label:"Q4 — staleTime",text:"Que controle l'option staleTime ?",options:["Le delai avant de supprimer les donnees du cache","La duree pendant laquelle les donnees sont considerees fraiches et ne seront pas re-fetchees","Le timeout de la requete","Le temps d'affichage du spinner"],answer:1,explanation:"staleTime definit combien de temps les donnees en cache sont 'fraiches'. Pendant ce temps, TanStack Query utilise le cache sans refaire d'appel reseau."},
  {label:"Q5 — Invalidation",text:"Que fait queryClient.invalidateQueries(['users']) ?",options:["Il supprime les utilisateurs de la base","Il marque les donnees 'users' comme perimees, declenchant un rafraichissement automatique","Il invalide le token d'authentification","Il vide tout le cache"],answer:1,explanation:"Invalider une query la marque comme 'stale' (perimee). Si un composant l'utilise, TanStack Query refetch automatiquement les donnees fraiches."}
]);

make('quiz-12-02-patterns-avances-vue-query.html','Quiz — TanStack Query patterns avances','Optimistic updates, prefetching, pagination infinie',[
  {label:"Q1 — Optimistic update",text:"Qu'est-ce qu'une mise a jour optimiste (optimistic update) ?",options:["Une mise a jour qui echoue toujours","Mettre a jour l'interface immediatement avant la confirmation du serveur, et annuler si le serveur echoue","Une mise a jour qui attend la reponse du serveur","Une mise a jour qui ne touche que le CSS"],answer:1,explanation:"L'optimistic update donne une impression de rapidite : l'UI change instantanement. Si le serveur confirme, parfait. S'il echoue, on rollback a l'etat precedent."},
  {label:"Q2 — onMutate",text:"A quoi sert le callback onMutate dans une mutation optimiste ?",options:["A lancer la requete reseau","A sauvegarder l'etat actuel du cache et le mettre a jour de maniere optimiste AVANT l'appel serveur","A fermer la modale","A valider les donnees"],answer:1,explanation:"onMutate s'execute avant la mutation. On y sauvegarde l'etat precedent (pour un rollback eventuel) et on met a jour le cache immediatement."},
  {label:"Q3 — Prefetching",text:"A quoi sert le prefetching de queries ?",options:["A telecharger tout le site","A precharger les donnees AVANT que l'utilisateur en ait besoin, pour une navigation instantanee","A compresser les requetes","A securiser le cache"],answer:1,explanation:"Le prefetching charge les donnees en arriere-plan (ex: quand la souris survole un lien). Quand l'utilisateur clique, les donnees sont deja en cache — affichage instantane."},
  {label:"Q4 — Pagination infinie",text:"Quel composable TanStack Query utilise-t-on pour le scroll infini ?",options:["useQuery avec pagination manuelle","useInfiniteQuery — il gere automatiquement les pages et le chargement incrementiel","usePagination","useScrollQuery"],answer:1,explanation:"useInfiniteQuery gere le chargement page par page avec fetchNextPage(). Il concatene les resultats et sait quand il n'y a plus de pages."},
  {label:"Q5 — Dependent queries",text:"Comment enchaine-t-on des queries dependantes (la 2e depend du resultat de la 1ere) ?",options:["On les appelle dans un setTimeout","On utilise l'option enabled pour activer la 2e query seulement quand la 1ere a ses donnees","On les met dans un Promise.all","On cree un composable custom obligatoirement"],answer:1,explanation:"enabled: !!userId.value desactive la query tant que userId est undefined. Quand la premiere query fournit l'id, enabled devient true et la 2e query se lance."}
]);

